mapper.select:
SELECT e.id AS eventId, m.id AS messageId, d.id AS dispatchId, e.event_type AS eventType, COALESCE(NULLIF(d.template_code, ''), NULLIF(m.template_code, ''), e.event_type) AS templateCode, t.template_name AS templateName, e.biz_type AS bizType, e.biz_id AS bizId, e.biz_no AS bizNo, d.channel_type AS channelType, c.channel_enabled AS channelEnabled, CASE WHEN d.id IS NOT NULL THEN d.receiver_type WHEN m.id IS NOT NULL THEN 'SYS_USER' ELSE NULL END AS receiverType, COALESCE(d.receiver_id, m.receiver_id, e.receiver_id) AS receiverId, COALESCE(d.receiver_address, m.receiver_name) AS receiverAddress, COALESCE(d.dispatch_status, m.todo_status, e.status) AS status, e.status AS eventStatus, m.todo_status AS messageStatus, d.dispatch_status AS dispatchStatus, COALESCE(d.result_code, m.invalid_reason) AS resultCode, CASE WHEN d.id IS NOT NULL THEN d.result_message WHEN m.invalid_reason IS NOT NULL THEN m.invalid_reason ELSE e.error_message END AS resultMessage, COALESCE(d.retry_count, e.retry_count, 0) AS retryCount, COALESCE(d.create_time, m.create_time, e.create_time) AS createTime, COALESCE(d.update_time, m.update_time, e.update_time) AS updateTime FROM sys_notify_event e LEFT JOIN ( SELECT sm.* FROM sys_notify_message sm INNER JOIN ( SELECT event_id, MAX(id) AS max_id FROM sys_notify_message GROUP BY event_id ) latest_sm ON latest_sm.max_id = sm.id ) m ON m.event_id = e.id LEFT JOIN ( SELECT sd.* FROM sys_notify_dispatch sd INNER JOIN ( SELECT event_id, MAX(id) AS max_id FROM sys_notify_dispatch GROUP BY event_id ) latest_sd ON latest_sd.max_id = sd.id ) d ON d.event_id = e.id LEFT JOIN sys_notify_template t ON t.scene_code = COALESCE(NULLIF(d.template_code, ''), NULLIF(m.template_code, '')) LEFT JOIN sys_notify_template_channel c ON c.scene_code = d.template_code AND c.channel_type = d.channel_type
AND e.biz_type = #{query.bizType}
AND e.biz_id = #{query.bizId}
AND e.biz_no LIKE CONCAT('%', #{query.bizNo}, '%')
AND e.event_type = #{query.eventType}
AND COALESCE(NULLIF(d.template_code, ''), NULLIF(m.template_code, ''), e.event_type) = #{query.templateCode}
AND d.channel_type = #{query.channelType}
AND ( (d.id IS NOT NULL AND d.receiver_type = #{query.receiverType}) OR (m.id IS NOT NULL AND #{query.receiverType} = 'SYS_USER') )
AND COALESCE(d.receiver_id, m.receiver_id, e.receiver_id) = #{query.receiverId}
AND ( e.status = #{query.status} OR m.todo_status = #{query.status} OR d.dispatch_status = #{query.status} )
AND COALESCE(d.result_code, m.invalid_reason) = #{query.resultCode}
AND e.create_time >= #{query.beginTime}
AND e.create_time <= #{query.endTime}
ORDER BY e.create_time DESC, e.id DESC
